(function(){
  function createState(){return{cpaMode:'history',cpaStatus:'ativa',cpaAccount:'all',cpaProduct:'all',cpaCountry:'all',cpaPlatform:'all',cpaSelectedRange:null,cpaDatesReady:false}}
  function filterRows(all,state){return all.filter(x=>(state.cpaStatus==='all'||x.status===state.cpaStatus)&&(state.cpaAccount==='all'||x.account===state.cpaAccount)&&(state.cpaProduct==='all'||x.product===state.cpaProduct)&&(state.cpaCountry==='all'||x.check.countries.includes(state.cpaCountry))&&(state.cpaPlatform==='all'||x.check.platform===state.cpaPlatform))}
  function summarizeRows(rows,selectedRange,fmtNum){
    const groups=new Map();for(const row of rows){const key=row.check.range==null?'other':String(row.check.range),group=groups.get(key)||{key,label:row.check.range==null?'Outras':`${fmtNum(row.check.range,row.check.range%1?1:0)}%`,range:row.check.range,rows:[]};group.rows.push(row);groups.set(key,group)}const list=[...groups.values()].sort((a,b)=>(a.range??999)-(b.range??999));if(!list.some(x=>x.key===selectedRange))selectedRange=list[0]?.key||null;const sum=(items,path)=>items.reduce((total,item)=>total+Number(path(item)||0),0),summaries=list.map(g=>{const investment=sum(g.rows,x=>x.totals.investment),conversions=sum(g.rows,x=>x.totals.conversions),commission=sum(g.rows,x=>x.totals.commission),profit=commission-investment,roi=investment>0?profit/investment*100:null;return{...g,active:g.rows.filter(x=>x.status==='ativa').length,investment,conversions,commission,profit,actualCpa:conversions>0?investment/conversions:null,roi,divergences:g.rows.filter(x=>['review','bad'].includes(x.check.status)).length}}),totalInvestment=sum(rows,x=>x.totals.investment),totalConversions=sum(rows,x=>x.totals.conversions),totalCommission=sum(rows,x=>x.totals.commission),totalProfit=totalCommission-totalInvestment,totalRoi=totalInvestment>0?totalProfit/totalInvestment*100:null,alerts=rows.filter(x=>['review','bad'].includes(x.check.status)).length;
    return{list,summaries,totalInvestment,totalConversions,totalCommission,totalProfit,totalRoi,alerts,selectedRange};
  }
    function productsByRange(rows){const groups=new Map();for(const row of rows){const key=row.check.range==null?'other':String(row.check.range),group=groups.get(key)||{key,label:row.check.range==null?'Sem faixa':`${String(row.check.range)}%`,range:row.check.range,products:new Set()};group.products.add(row.product.toLocaleLowerCase('pt-BR'));groups.set(key,group)}return[...groups.values()].map(group=>({...group,count:group.products.size})).sort((a,b)=>(a.range??Number.POSITIVE_INFINITY)-(b.range??Number.POSITIVE_INFINITY))}
  window.CpaDomain=Object.freeze({createState,filterRows,summarizeRows,productsByRange});
})();
